                    result.ErrorMessage = string.Format("{0}", objdb.GetParameterValue("errmsg"));
                    result.ErrorHandler.Add(0, string.Format("{0}", objdb.GetParameterValue("accountremarkdate")));

                    return result;
                }
            }
            catch (Exception ex)
            {
                LogExtensions.ExceptionHandler(ex);
                throw ex;
            }
        }
      

